from subprocess import CalledProcessError
from lxml import etree
from ute_fsmaccess import ute_fsmaccess
from ute_ipsec.commissioning import Commissioning
from ute_ipsec.trs_config import TrsConfig
from ute_ipsec.exceptions import VlansNotSupportedError, IncorrectConfigurationError


class BtsVlans(object):
    """All Vlans operations on BTS handled here"""

    def __init__(self, testline_vlan_ids, sec_gw_ip):
        self.testline_vlan_ids = testline_vlan_ids
        self.commissioning_ops = Commissioning()
        self.sec_gw_ip = sec_gw_ip
        self.ute_fsmaccess = ute_fsmaccess()
        self.trs_config = TrsConfig()

    def create(self, number_of_vlans, ip_version, configuration, config_file):
        """Creates VLANs on the bts"""
        self._check_vlans_support(number_of_vlans)
        if config_file == 'default':
            if not self.trs_config.is_vlan_existing(ip_version):
                if self.sec_gw_ip == '127.0.0.1':
                    self.commissioning_ops.create_vlans_on_bts(self.testline_vlan_ids, ip_version, configuration)
                else:
                    self.commissioning_ops.create_vlans_on_bts_with_extern_ipsec(self.testline_vlan_ids, ip_version)
            else:
                self.commissioning_ops.update_application_addresses_with_vlans()
        else:
            self.commissioning_ops.perform_commissioning_using_config_file(self.testline_vlan_ids, config_file)

    def delete(self, number_of_vlans, ip_version, config_file):
        """Removes vlans on BTS"""
        if config_file == 'default':
            if self.trs_config.is_vlan_existing(ip_version):
                self.commissioning_ops.remove_vlans(number_of_vlans, ip_version)

    def _check_vlans_support(self, number_of_vlans):
        if number_of_vlans <= len(self.testline_vlan_ids):
            self.testline_vlan_ids = self.testline_vlan_ids[:number_of_vlans]
        elif number_of_vlans > len(self.testline_vlan_ids):
            raise VlansNotSupportedError('On testline', number_of_vlans)


class SecgwVlans(object):
    """All Vlans operations on secgw handled here"""

    PLANE_IPS = ['10.0.3.209', '10.0.3.213', '10.0.3.217', '10.0.3.221', '10.0.3.225', '10.0.3.229']
    BROADCAST_IPS = ['10.0.3.211', '10.0.3.215', '10.0.3.219', '10.0.3.223', '10.0.3.227', '10.0.3.231']
    PLANE_IPS_8IP_CONFIG = ['10.0.3.233', '10.0.3.237', '10.0.3.241', '10.0.3.245', '10.0.3.249', '10.0.3.253']
    BROADCAST_IPS_8IP_CONFIG = ['10.0.3.235', '10.0.3.239', '10.0.3.243', '10.0.3.247', '10.0.3.251', '10.0.3.255']
    BTS_APPLICATION_ADDRESSES = ['10.0.3.210', '10.0.3.214', '10.0.3.218', '10.0.3.222']
    BTS_INTERFACE_ADDRESSES = ['10.0.3.234', '10.0.3.238', '10.0.3.242', '10.0.3.246']
    PLANE_IPS_Ipv6 = ['fc00::3:6', 'fc00::3:a', 'fc00::3:e']
    VM_IPv6_ADDRESS = 'fc00::1'
    SGW1_ADDRESS = 'fc00::6'
    ETHERNET = 'eth3'

    def __init__(self, testline_vlan_ids, executor, sec_gw_ip):
        self.testline_vlan_ids = testline_vlan_ids
        self.commissioning_ops = Commissioning()
        self.executor = executor
        self.sec_gw_ip = sec_gw_ip

    def create(self, number_of_vlans, ip_version, configuration, config_file):
        """Creates VLANs on the secgw"""
        self._check_vlans_support_on_testline(number_of_vlans, config_file)
        for vlan_id in self.testline_vlan_ids:
            self._create_each_vlan(self.ETHERNET, vlan_id, ip_version, configuration, config_file)
        if ip_version == 6:
            self._add_ipv6_config(self.ETHERNET)
        if configuration == '8 ip':
            self._add_routes_to_application_address()

    def _fetch_number_of_vlans(self, config_file):
        root_element = etree.parse(config_file)
        namespaces = {'r': 'raml21.xsd'}
        xpath = "/r:raml/r:cmData/r:managedObject[@class='NOKLTE:IVIF']"
        number_of_vlans = root_element.xpath(xpath, namespaces=namespaces)
        return len(number_of_vlans)

    def _is_moc_existing(self, moc_name, config_file):
        root_element = etree.parse(config_file)
        namespaces = {'r': 'raml21.xsd'}
        xpath = "/r:raml/r:cmData/r:managedObject[@class=" + "'" + moc_name + "'" + "]"
        moc_xpath = root_element.xpath(xpath, namespaces=namespaces)
        if len(moc_xpath) != 0:
            return True

    def _get_ip_address(self, moc_name, list_name, parameter_name, config_file):
        root_element = etree.parse(config_file)
        namespaces = {'r': 'raml21.xsd'}
        xpath = "/r:raml/r:cmData/r:managedObject[@class=" + "'" + moc_name + "'" + "]/r:list[@name=" \
                + "'" + list_name + "'" + "]/r:item/r:p[@name=" + "'" + parameter_name + "'" + "]"
        ip_address_xpath = root_element.xpath(xpath, namespaces=namespaces)
        ip_address = []
        for i in range(len(ip_address_xpath)):
            ip_address.append(ip_address_xpath[i].text)
        return ip_address

    def _check_vlans_support_on_testline(self, number_of_vlans, config_file):
        if config_file == 'default':
            self._check_vlans_support(number_of_vlans)
        else:
            no_of_vlans_in_config_file = self._fetch_number_of_vlans(config_file)
            self._check_vlans_support(no_of_vlans_in_config_file)

    def _check_vlans_support(self, number_of_vlans):
        if number_of_vlans <= len(self.testline_vlan_ids):
            self.testline_vlan_ids = self.testline_vlan_ids[:number_of_vlans]
        elif number_of_vlans > len(self.testline_vlan_ids):
            raise VlansNotSupportedError('On testline', number_of_vlans)

    def _create_each_vlan(self, eth, vlan_id, ip_version, configuration, config_file):
        vlanid_pos = self.testline_vlan_ids.index(vlan_id)
        if not self._is_vlan_existing(eth, vlan_id):
            self._add_ip_link(eth, vlan_id)
            self._add_ip_address(eth, vlan_id, vlanid_pos, configuration, config_file)
            self._set_ip_link_state(eth, vlan_id, 'up')
            if ip_version == 6 and vlanid_pos < 3:
                self._add_ipv6_address(self.ETHERNET, vlan_id, vlanid_pos)

    def _add_ip_link(self, eth, vlan_id):
        command_template = 'sudo ip link add link {eth_num} name {eth_num}.{vlan_num} type vlan id {vlan_num}'
        command = command_template.format(eth_num=eth, vlan_num=vlan_id)
        self.executor.execute_command_on_secgw(command)

    def _add_ip_address(self, eth, vlan_id, vlanid_pos, configuration, config_file):
        if config_file == 'default':
            self._add_ipv4_addresses(eth, vlan_id, vlanid_pos, configuration)
        else:
            self._add_ips_incase_of_config_file(eth, vlan_id, vlanid_pos, configuration, config_file)

    def _add_ipv4_addresses(self, eth, vlan_id, vlanid_pos, configuration):
        command_template = 'sudo ip addr add {pln_ip}/30 brd {brd_ip} dev {eth_num}.{vlan_num}'
        if configuration == 'basic':
            command = command_template.format(pln_ip=self.PLANE_IPS[vlanid_pos], brd_ip=self.BROADCAST_IPS[vlanid_pos],
                                              eth_num=eth, vlan_num=vlan_id)
        elif configuration == '8 ip':
            command = command_template.format(pln_ip=self.PLANE_IPS_8IP_CONFIG[vlanid_pos],
                                              brd_ip=self.BROADCAST_IPS_8IP_CONFIG[vlanid_pos],
                                              eth_num=eth, vlan_num=vlan_id)
        self.executor.execute_command_on_secgw(command)

    def _add_ips_incase_of_config_file(self, eth, vlan_id, vlanid_pos, configuration, config_file):
        self._add_ipv4_addresses(eth, vlan_id, vlanid_pos, configuration)
        if self._is_moc_existing('NOKLTE:IPRTV6', config_file):
            gateway_ip_address = self._get_ip_address('NOKLTE:IPRTV6', 'staticIpv6Routes', 'gatewayIpv6Addr',
                                                      config_file)
            self._add_ipv6_from_config_file(gateway_ip_address)
            if vlanid_pos < 3 or vlanid_pos >= 4:
                self._add_ipv6_addr_from_config(eth, vlan_id, vlanid_pos, gateway_ip_address)

    def _add_ipv6_addr_from_config(self, eth, vlan_id, vlanid_pos, gateway_ip_address):
        command_template = 'sudo ifconfig {eth_num}.{vlan_num} inet6 add {pln_ipv6}/126'
        if vlanid_pos >= 4:
            command = command_template.format(eth_num=eth, vlan_num=vlan_id,
                                              pln_ipv6=gateway_ip_address[vlanid_pos - 1])
        else:
            command = command_template.format(eth_num=eth, vlan_num=vlan_id, pln_ipv6=gateway_ip_address[vlanid_pos])
        self.executor.execute_command_on_secgw(command)

    def _add_ipv6_from_config_file(self, gateway_ip_address):
        console_ipv6_output = self._is_ipv6_address_in_list(gateway_ip_address)
        if console_ipv6_output:
            self._add_ipv6_config(self.ETHERNET)
            gateway_ip_address.pop(console_ipv6_output - 1)

    def _is_ipv6_address_in_list(self, gateway_ip_address):
        ipv6_flag = 0
        if self.SGW1_ADDRESS in gateway_ip_address and self.VM_IPv6_ADDRESS not in gateway_ip_address:
            ipv6_flag = 1
        elif self.SGW1_ADDRESS not in gateway_ip_address and self.VM_IPv6_ADDRESS in gateway_ip_address:
            ipv6_flag = 1
        elif self.SGW1_ADDRESS and self.VM_IPv6_ADDRESS in gateway_ip_address:
            ipv6_flag = 0
        else:
            raise IncorrectConfigurationError('In Config file')
        return ipv6_flag

    def _add_ipv6_config(self, eth):
        console_output = self._is_ipv6_config_existing(eth)
        if not console_output:
            command_template = 'sudo ifconfig {eth_num} inet6 add {sgw_ipv6}/116'
            if self.sec_gw_ip == '127.0.0.1':
                command = command_template.format(eth_num=eth, sgw_ipv6=self.VM_IPv6_ADDRESS)
            else:
                command = command_template.format(eth_num=eth, sgw_ipv6=self.SGW1_ADDRESS)
            self.executor.execute_command_on_secgw(command)

    def _add_ipv6_address(self, eth, vlan_id, vlanid_pos):
        command_template = 'sudo ifconfig {eth_num}.{vlan_num} inet6 add {pln_ipv6}/126'
        command = command_template.format(eth_num=eth, vlan_num=vlan_id, pln_ipv6=self.PLANE_IPS_Ipv6[vlanid_pos])
        self.executor.execute_command_on_secgw(command)

    def _del_ipv6_address_if_exist(self, eth):
        console_output = self._is_ipv6_config_existing(eth)
        if console_output:
            command_template = 'sudo ifconfig {eth_num} inet6 del {sgw_ipv6}/116'
            if self.sec_gw_ip == '127.0.0.1':
                command = command_template.format(eth_num=eth, sgw_ipv6=self.VM_IPv6_ADDRESS)
            else:
                command = command_template.format(eth_num=eth, sgw_ipv6=self.SGW1_ADDRESS)
            self.executor.execute_command_on_secgw(command)

    def _add_routes_to_application_address(self):
        for index in range(len(self.testline_vlan_ids)):
            command_template = 'sudo ip route add {application_address} via {interface_address}'
            command = command_template.format(application_address=self.BTS_APPLICATION_ADDRESSES[index],
                                              interface_address=self.BTS_INTERFACE_ADDRESSES[index])
            self.executor.execute_command_on_secgw(command)

    def delete(self, number_of_vlans):
        """Deletes VLANs on the secgw"""
        self._del_ipv6_address_if_exist(self.ETHERNET)
        number_of_vlans = self._get_no_of_vlans_on_sgw()
        self._check_vlans_support(number_of_vlans)
        for vlan_id in self.testline_vlan_ids:
            self._delete_each_vlan(self.ETHERNET, vlan_id)

    def _get_no_of_vlans_on_sgw(self):
        no_of_virtual_interfaces = "sudo ifconfig | grep eth3: | wc -l 2> /dev/null"
        command = "sudo ifconfig -a | grep " + "'" + "eth3.*" + "'" + " | wc -l 2> /dev/null"
        return int(self.executor.execute_command_on_secgw(command)) - int(self.executor.execute_command_on_secgw(no_of_virtual_interfaces)) - 1

    def _delete_each_vlan(self, eth, vlan_id):
        if self._is_vlan_existing(eth, vlan_id):
            self._set_ip_link_state(eth, vlan_id, 'down')
            self._delete_vlan(eth, vlan_id)

    def _set_ip_link_state(self, eth, vlan_id, state):
        command_template = 'sudo ip link set dev {eth_num}.{vlan_num} {state}'
        command = command_template.format(eth_num=eth, vlan_num=vlan_id, state=state)
        self.executor.execute_command_on_secgw(command)

    def _delete_vlan(self, eth, vlan_id):
        command_template = 'sudo ip link delete {eth_num}.{vlan_num}'
        command = command_template.format(eth_num=eth, vlan_num=vlan_id)
        self.executor.execute_command_on_secgw(command)

    def _is_vlan_existing(self, eth, vlan_id):
        command_template = 'sudo ifconfig {eth_num}.{vlan_num} 2> /dev/null'
        command = command_template.format(eth_num=eth, vlan_num=vlan_id)
        try:
            self.executor.execute_command_on_secgw(command)
            return True
        except CalledProcessError:
            return False

    def _is_ipv6_config_existing(self, eth):
        command_template = 'sudo ifconfig {eth_num} | grep inet6 | grep -i Global 2> /dev/null'
        command = command_template.format(eth_num=eth, vm_ipv6=self.VM_IPv6_ADDRESS)
        try:
            return self.executor.execute_command_on_secgw(command)
        except CalledProcessError:
            return False
